:fixed;inset:0;z-index:12900;display:none;background:rgba(0,17,49,.22)}.aut-overlay.open{display:block}.aut-drawer{position:fixed;z-index:13000;top:0;right:0;width:min(430px,100vw);height:100vh;background:#fff;border-left:1px solid #dfe6ea;box-shadow:-14px 0 35px rgba(0,17,49,.12);transform:translateX(100%);transition:transform .2s ease;display:flex;flex-direction:column}.aut-drawer.open{transform:translateX(0)}.aut-drawer-head{display:flex;align-items:flex-start;gap:10px;padding:20px 18px 10px}.aut-title-input{width:100%;border:0;border-bottom:1px dotted #294958;background:transparent;color:#082b3a;font:inherit;font-size:20px;font-weight:700;outline:none}.aut-close{border:0;background:transparent;color:#173644;font-size:26px;cursor:pointer}.aut-status{display:none;margin:0 18px 4px;font-size:10px;color:#2f7f24}.aut-status.show{display:block}.aut-builder{flex:1;overflow:auto;padding:8px 18px 90px}.aut-step-label{display:flex;align-items:center;gap:8px;margin:5px 0 -8px;color:#516b79;font-size:10px;font-style:italic}.aut-step-label:before,.aut-step-label:after{content:"";height:1px;background:#dde5e9;flex:1}.aut-node{position:relative;margin:8px 0;padding:12px;border:1px solid #dce4e9;border-radius:8px;background:#fff}.aut-node-row{display:flex;align-items:center;gap:10px}.aut-node-icon{width:34px;height:34px;display:grid;place-items:center;flex:0 0 auto;border-radius:7px;background:#f2f1ee;color:#174457}.aut-node-text{flex:1;min-width:0;color:#425e6c;font-size:12px;line-height:1.5}.aut-node-text button{padding:0;border:0;border-bottom:1px solid #5b9c39;background:transparent;color:#39882a;font:inherit;font-weight:700;cursor:pointer}.aut-trash{border:0;background:transparent;color:#e84b49;font-size:18px;cursor:pointer}.aut-plus-wrap{display:flex;justify-content:center;height:34px;position:relative}.aut-plus-wrap:before{content:"";position:absolute;left:50%;top:0;bottom:0;width:1px;background:#dce4e9}.aut-plus{position:relative;z-index:1;width:26px;height:26px;margin-top:4px;border:1px solid #dce4e9;border-radius:7px;background:#fff;color:#2f8c25;font-size:17px;cursor:pointer}.aut-placeholder{min-height:64px;display:flex;align-items:center;justify-content:center;border:1px solid #dce4e9;border-radius:8px;color:#39882a;font-size:12px;font-weight:700;text-decoration:underline;cursor:pointer}.aut-menu{position:absolute;z-index:13020;min-width:190px;padding:6px;background:#fff;border:1px solid #dce4e9;border-radius:8px;box-shadow:0 10px 25px rgba(0,17,49,.13)}.aut-menu button{display:block;width:100%;padding:9px 10px;border:0;border-radius:6px;background:#fff;color:#294958;text-align:left;font:inherit;font-size:12px;cursor:pointer}.aut-menu button:hover{background:#f4f7f8}.aut-pop{margin-top:8px;padding:9px;border:1px solid #dce4e9;border-radius:8px;background:#fff}.aut-grid2{display:grid;grid-template-columns:1fr 1fr;gap:8px}.aut-input,.aut-select,.aut-textarea{width:100%;border:1px solid #d4dee4;border-radius:7px;background:#fff;color:#173644;font:inherit;font-size:12px;outline:none}.aut-input,.aut-select{height:38px;padding:0 10px}.aut-textarea{min-height:84px;padding:10px;resize:vertical}.aut-input:focus,.aut-select:focus,.aut-textarea:focus{border-color:#74b824;box-shadow:0 0 0 2px rgba(116,184,36,.12)}.aut-value-list{max-height:190px;overflow:auto;margin-top:7px;border:1px solid #e2e8eb;border-radius:7px}.aut-value-item{display:block;width:100%;padding:9px 10px;border:0;border-bottom:1px solid #edf1f3;background:#fff;color:#294958;text-align:left;font:inherit;font-size:11px;cursor:pointer}.aut-value-item:last-child{border-bottom:0}.aut-value-item:hover{background:#f6f9fa}.aut-drawer-foot{position:absolute;left:0;right:0;bottom:0;display:flex;gap:9px;padding:12px 18px;background:#fff;border-top:1px solid #e2e8eb}.aut-drawer-foot .primary{flex:1}.aut-more{position:relative}.aut-more-menu{position:absolute;right:0;bottom:44px;min-width:155px;padding:6px;background:#fff;border:1px solid #dce4e9;border-radius:8px;box-shadow:0 10px 25px rgba(0,17,49,.14);display:none}.aut-more-menu.open{display:block}.aut-more-menu button{display:block;width:100%;padding:9px;border:0;background:#fff;text-align:left;font:inherit;font-size:11px;cursor:pointer}.aut-more-menu button:hover{background:#f4f7f8}.aut-loading{padding:30px;color:#6f7b90;font-size:12px}.aut-disabled{opacity:.5;pointer-events:none}.aut-badge{display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border-radius:999px;background:#eef7e8;color:#2f7f24;font-size:9px}.aut-badge:before{content:"";width:6px;height:6px;border-radius:50%;background:#2f8c25}.aut-badge.off{background:#f0f2f4;color:#60737d}.aut-badge.off:before{background:#9aa9b0}
