<script>
(function(){
'use strict';
var csrf=<?= json_encode($automationCsrf,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;
var api='api/automations.php';
var meta=null, automations=[], current=null, editingId=0, openMenu=null;
var drawer=document.getElementById('automationDrawer'), overlay=document.getElementById('automationOverlay'), builder=document.getElementById('automationBuilder'), titleInput=document.getElementById('automationTitle'), saveBtn=document.getElementById('saveAutomation');
function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}
function toast(t,m){if(typeof window.fieldplxToast==='function')window.fieldplxToast(t,m)}
function fd(action){var f=new FormData();f.append('action',action);f.append('csrf_token',csrf);return f}
function req(f){return fetch(api,{method:'POST',body:f,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.text().then(function(t){var d;try{d=JSON.parse(t)}catch(e){throw new Error('Invalid server response.')}if(!r.ok||!d.success)throw new Error(d.message||'Request failed.');return d})})}
function icon(k){if(k==='archive'||k==='update_status')return '▣';if(k==='notify')return '▷';if(k==='add_tag')return '⊕';if(k==='filter')return '≡';return '▣'}
function relationText(a){var n=Number(a.trigger_offset_value||0), rel=a.trigger_relation||'after', tr=a.trigger_name||'event';if(rel==='on'||n===0)return 'On the day '+tr;return n+' day(s) '+rel+' '+tr}
function sectionName(key){return key==='quote'?'Quotes':key==='invoice'?'Invoices':key==='request'?'Requests':key}
function renderCards(){var root=document.getElementById('automationContent');if(!meta){root.innerHTML='<div class="aut-loading">Loading automations...</div>';return}var html='';meta.entities.forEach(function(e){var list=automations.filter(function(a){return a.entity_key===e.entity_key});var templates=(meta.templates||[]).filter(function(t){return t.entity_key===e.entity_key});html+='<section class="aut-section"><h2>'+esc(e.entity_name)+'</h2><div class="aut-cards">';templates.forEach(function(t){var found=list.find(function(a){return a.template_key===t.template_key});var title=found?found.title:t.title;html+='<article class="aut-card" data-template="'+esc(t.template_key)+'" data-entity="'+esc(e.entity_key)+'"'+(found?' data-id="'+Number(found.id)+'"':'')+'><div class="aut-card-icons"><span class="aut-ico">▣</span><span class="aut-arrow">→</span><span class="aut-ico">'+icon(t.action_key)+'</span></div><div class="aut-card-title">'+esc(title)+'</div><div class="aut-card-meta">'+(found?(Number(found.is_active)===1?'Active':'Disabled'):'Template')+'</div></article>'});list.filter(function(a){return !a.template_key}).forEach(function(a){html+='<article class="aut-card custom" data-id="'+Number(a.id)+'"><div class="aut-card-icons"><span class="aut-ico">▣</span><span class="aut-arrow">→</span><span class="aut-ico">'+icon(a.primary_action_key)+'</span></div><div class="aut-card-title">'+esc(a.title)+'</div><div class="aut-card-meta">'+(Number(a.is_active)===1?'Active':'Disabled')+' · '+esc(relationText(a))+'</div></article>'});html+='</div></section>'});root.innerHTML=html;root.querySelectorAll('.aut-card').forEach(function(c){c.onclick=function(){var id=Number(c.getAttribute('data-id')||0);if(id)openExisting(id);else openTemplate(c.getAttribute('data-template'),c.getAttribute('data-entity'))}})}
function defaultRule(entity){var triggers=meta.triggers.filter(function(x){return x.entity_key===entity});return {id:0,title:'',entity_key:entity,trigger_id:triggers.length?Number(triggers[0].id):0,trigger_relation:triggers.length?triggers[0].default_relation:'after',trigger_offset_value:triggers.length?Number(triggers[0].default_offset||0):0,is_active:1,template_key:null,conditions:[],actions:[]}}
function openDrawer(){drawer.classList.add('open');overlay.classList.add('open');drawer.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}
function closeDrawer(){drawer.classList.remove('open');overlay.classList.remove('open');drawer.setAttribute('aria-hidden','true');document.body.style.overflow='';closeFloating()}
function findMaster(list,id){id=Number(id||0);return list.find(function(x){return Number(x.id)===id})||null}
function openTemplate(key,entity){var tpl=(meta.templates||[]).find(function(t){return t.template_key===key});current=defaultRule(entity);if(tpl){current.title=tpl.title;current.template_key=tpl.template_key;var tr=meta.triggers.find(function(x){return x.trigger_key===tpl.trigger_key&&x.entity_key===entity});if(tr){current.trigger_id=Number(tr.id);current.trigger_relation=tpl.relation;current.trigger_offset_value=Number(tpl.offset||0)}(tpl.conditions||[]).forEach(function(c){var cm=meta.conditions.find(function(x){return x.entity_key===entity&&x.condition_key===c.condition_key});if(cm)current.conditions.push({condition_id:Number(cm.id),operator_key:c.operator_key,value_id:c.value_id||null,value_text:c.value_text||''})});(tpl.actions||[]).forEach(function(a){var am=meta.actions.find(function(x){return x.entity_key===entity&&x.action_key===a.action_key});if(am)current.actions.push({action_id:Number(am.id),value_id:a.value_id||null,value_text:a.value_text||'',config:a.config||{}})})}editingId=0;titleInput.value=current.title;openDrawer();renderBuilder()}
function openExisting(id){var f=fd('get');f.append('automation_id',String(id));req(f).then(function(d){current=d.automation;editingId=Number(current.id);titleInput.value=current.title||'';openDrawer();renderBuilder()}).catch(function(e){toast('error',e.message)})}
function triggerMaster(){return findMaster(meta.triggers,current.trigger_id)}
function conditionMaster(row){return findMaster(meta.conditions,row.condition_id)}
function actionMaster(row){return findMaster(meta.actions,row.action_id)}
function renderBuilder(){if(!current)return;var tr=triggerMaster();var h='';if(editingId){h+='<div style="margin-bottom:10px">'+(Number(current.is_active)===1?'<span class="aut-badge">Active</span>':'<span class="aut-badge off">Disabled</span>')+'</div>'}h+='<div class="aut-step-label">When this happens</div><div class="aut-node"><div class="aut-node-row"><div class="aut-node-icon">▣</div><div class="aut-node-text"><button data-pick="timing">'+esc(tr?relationText({trigger_offset_value:current.trigger_offset_value,trigger_relation:current.trigger_relation,trigger_name:tr.trigger_name}):'Choose trigger')+'</button></div><button class="aut-trash" data-clear-trigger>⌫</button></div><div id="triggerEditor"></div></div>';
if(current.conditions.length){h+='<div class="aut-step-label">And only if</div>';current.conditions.forEach(function(c,i){var cm=conditionMaster(c);h+='<div class="aut-node"><div class="aut-node-row"><div class="aut-node-icon">≡</div><div class="aut-node-text">'+esc(cm?cm.condition_name:'Condition')+' <button data-edit-condition="'+i+'">'+esc(conditionSentence(c,cm))+'</button></div><button class="aut-trash" data-remove-condition="'+i+'">⌫</button></div><div id="conditionEditor'+i+'"></div></div>'})}
h+='<div class="aut-plus-wrap"><button class="aut-plus" data-add-condition>+</button></div>';
if(current.actions.length){h+='<div class="aut-step-label">Then do this</div>';current.actions.forEach(function(a,i){var am=actionMaster(a);h+='<div class="aut-node"><div class="aut-node-row"><div class="aut-node-icon">'+icon(am?am.action_key:'')+'</div><div class="aut-node-text">'+esc(am?am.action_name:'Action')+' <button data-edit-action="'+i+'">'+esc(actionSentence(a,am))+'</button></div><button class="aut-trash" data-remove-action="'+i+'">⌫</button></div><div id="actionEditor'+i+'"></div></div>'});h+='<div class="aut-plus-wrap"><button class="aut-plus" data-add-action>+</button></div>'}else{h+='<div class="aut-placeholder" data-add-action>Then do this</div>'}
builder.innerHTML=h;wireBuilder();validate()}
function conditionSentence(c,cm){if(!cm)return 'configure';var op=c.operator_key||'is',v=c.value_text||lookupValue(cm.value_source,c.value_id)||'this value';if(cm.condition_key==='status')return (op==='is_not'?'is not ':'is ')+v;if(cm.condition_key==='client_tag')return (op==='not_include'?'do not include ':'include ')+v;if(cm.condition_key==='line_item')return (op==='not_include'?'do not include ':'include ')+v;return op+' '+v}
function actionSentence(a,am){if(!am)return 'configure';if(am.action_key==='notify')return (a.config&&a.config.channel==='in_app'?'in app':'customer by email');if(am.action_key==='add_tag')return lookupValue('client_tag',a.value_id)||a.value_text||'this tag';if(am.action_key==='update_status')return 'to '+(a.value_text||lookupValue('status',a.value_id)||'this status');return a.value_text||'configure'}
function lookupValue(source,id){id=Number(id||0);if(source==='client_tag'){var x=(meta.tags||[]).find(function(v){return Number(v.id)===id});return x?x.name:''}if(source==='line_item'){var y=(meta.line_items||[]).find(function(v){return Number(v.id)===id});return y?y.name:''}return ''}
function wireBuilder(){var b=builder.querySelector('[data-pick="timing"]');if(b)b.onclick=function(){renderTriggerEditor()};var clear=builder.querySelector('[data-clear-trigger]');if(clear)clear.onclick=function(){current.trigger_id=0;renderBuilder()};builder.querySelectorAll('[data-add-condition]').forEach(function(x){x.onclick=function(){showConditionMenu(x)}});builder.querySelectorAll('[data-add-action]').forEach(function(x){x.onclick=function(){showActionMenu(x)}});builder.querySelectorAll('[data-remove-condition]').forEach(function(x){x.onclick=function(){current.conditions.splice(Number(x.getAttribute('data-remove-condition')),1);renderBuilder()}});builder.querySelectorAll('[data-remove-action]').forEach(function(x){x.onclick=function(){current.actions.splice(Number(x.getAttribute('data-remove-action')),1);renderBuilder()}});builder.querySelectorAll('[data-edit-condition]').forEach(function(x){x.onclick=function(){renderConditionEditor(Number(x.getAttribute('data-edit-condition')))}});builder.querySelectorAll('[data-edit-action]').forEach(function(x){x.onclick=function(){renderActionEditor(Number(x.getAttribute('data-edit-action')))}})}
function renderTriggerEditor(){var tr=triggerMaster(), box=document.getElementById('triggerEditor');var choices=meta.triggers.filter(function(x){return x.entity_key===current.entity_key});box.innerHTML='<div class="aut-pop"><div class="aut-grid2"><select class="aut-select" id="trMaster">'+choices.map(function(x){return '<option value="'+x.id+'" '+(Number(x.id)===Number(current.trigger_id)?'selected':'')+'>'+esc(x.trigger_name)+'</option>'}).join('')+'</select><select class="aut-select" id="trRelation"><option value="before">Before</option><option value="on">On the day</option><option value="after">After</option></select></div><div style="margin-top:8px"><input class="aut-input" type="number" min="0" max="3650" id="trOffset" value="'+Number(current.trigger_offset_value||0)+'" placeholder="Days"></div></div>';var rel=document.getElementById('trRelation');rel.value=current.trigger_relation||'after';function apply(){current.trigger_id=Number(document.getElementById('trMaster').value);current.trigger_relation=rel.value;current.trigger_offset_value=Math.max(0,Number(document.getElementById('trOffset').value||0));validate()}box.querySelectorAll('select,input').forEach(function(x){x.onchange=apply;x.oninput=apply});document.getElementById('trMaster').onchange=function(){current.trigger_id=Number(this.value);var n=findMaster(meta.triggers,current.trigger_id);if(n){current.trigger_relation=n.default_relation;current.trigger_offset_value=Number(n.default_offset||0)}renderBuilder();renderTriggerEditor()}}
function showConditionMenu(anchor){closeFloating();var list=meta.conditions.filter(function(x){return x.entity_key===current.entity_key});var m=document.createElement('div');m.className='aut-menu';m.innerHTML='<button disabled style="font-weight:700">Add condition</button>'+list.map(function(x){return '<button data-cm="'+x.id+'">'+esc(x.condition_name)+'</button>'}).join('');document.body.appendChild(m);place(m,anchor);openMenu=m;m.querySelectorAll('[data-cm]').forEach(function(x){x.onclick=function(){current.conditions.push({condition_id:Number(x.getAttribute('data-cm')),operator_key:'is',value_id:null,value_text:''});closeFloating();renderBuilder();renderConditionEditor(current.conditions.length-1)}})}
function showActionMenu(anchor){closeFloating();var list=meta.actions.filter(function(x){return x.entity_key===current.entity_key});var m=document.createElement('div');m.className='aut-menu';m.innerHTML=list.map(function(x){return '<button data-am="'+x.id+'">'+icon(x.action_key)+' &nbsp; '+esc(x.action_name)+'</button>'}).join('');document.body.appendChild(m);place(m,anchor);openMenu=m;m.querySelectorAll('[data-am]').forEach(function(x){x.onclick=function(){var am=findMaster(meta.actions,Number(x.getAttribute('data-am')));current.actions.push({action_id:Number(am.id),value_id:null,value_text:'',config:am.action_key==='notify'?{channel:'email',recipient:'client',subject:'',message:''}:{}});closeFloating();renderBuilder();renderActionEditor(current.actions.length-1)}})}
function renderConditionEditor(i){var c=current.conditions[i],cm=conditionMaster(c),box=document.getElementById('conditionEditor'+i);if(!cm||!box)return;var ops=[];try{ops=JSON.parse(cm.allowed_operators_json||'[]')}catch(e){};if(!ops.length)ops=['is'];var vals=[];if(cm.value_source==='status')vals=(meta.statuses[current.entity_key]||[]).map(function(s){return {id:'',name:s}});if(cm.value_source==='client_tag')vals=meta.tags||[];if(cm.value_source==='line_item')vals=meta.line_items||[];box.innerHTML='<div class="aut-pop"><select class="aut-select" data-op>'+ops.map(function(o){return '<option value="'+esc(o)+'" '+(o===c.operator_key?'selected':'')+'>'+esc(o.replace('_',' '))+'</option>'}).join('')+'</select><div class="aut-value-list">'+vals.map(function(v){var selected=(cm.value_source==='status'?String(c.value_text)===String(v.name):Number(c.value_id)===Number(v.id));return '<button class="aut-value-item" data-value-id="'+(v.id||'')+'" data-value-text="'+esc(v.name)+'">'+(selected?'✓ ':'')+esc(v.name)+'</button>'}).join('')+'</div></div>';box.querySelector('[data-op]').onchange=function(){c.operator_key=this.value;validate()};box.querySelectorAll('.aut-value-item').forEach(function(x){x.onclick=function(){c.value_id=x.getAttribute('data-value-id')?Number(x.getAttribute('data-value-id')):null;c.value_text=x.getAttribute('data-value-text');renderBuilder()}})}
function renderActionEditor(i){var a=current.actions[i],am=actionMaster(a),box=document.getElementById('actionEditor'+i);if(!am||!box)return;if(am.action_key==='notify'){var cfg=a.config||{};box.innerHTML='<div class="aut-pop"><select class="aut-select" data-channel><option value="email">Email customer</option><option value="in_app">In-app notification</option></select><input class="aut-input" style="margin-top:8px" data-subject placeholder="Subject" value="'+esc(cfg.subject||'')+'"><textarea class="aut-textarea" style="margin-top:8px" data-message placeholder="Message">'+esc(cfg.message||'')+'</textarea></div>';box.querySelector('[data-channel]').value=cfg.channel||'email';box.querySelectorAll('select,input,textarea').forEach(function(x){x.oninput=x.onchange=function(){a.config={channel:box.querySelector('[data-channel]').value,recipient:'client',subject:box.querySelector('[data-subject]').value,message:box.querySelector('[data-message]').value};validate()}});return}var vals=am.value_source==='client_tag'?(meta.tags||[]):(meta.statuses[current.entity_key]||[]).map(function(s){return {id:'',name:s}});box.innerHTML='<div class="aut-pop"><div class="aut-value-list">'+vals.map(function(v){return '<button class="aut-value-item" data-value-id="'+(v.id||'')+'" data-value-text="'+esc(v.name)+'">'+esc(v.name)+'</button>'}).join('')+'</div></div>';box.querySelectorAll('.aut-value-item').forEach(function(x){x.onclick=function(){a.value_id=x.getAttribute('data-value-id')?Number(x.getAttribute('data-value-id')):null;a.value_text=x.getAttribute('data-value-text');renderBuilder()}})}
function validate(){if(!current){saveBtn.disabled=true;return}var ok=String(titleInput.value||'').trim()!==''&&Number(current.trigger_id)>0&&current.actions.length>0;current.conditions.forEach(function(c){if(!c.value_text&&!c.value_id)ok=false});current.actions.forEach(function(a){var am=actionMaster(a);if(am&&am.action_key==='notify'){if(!a.config||!String(a.config.message||'').trim())ok=false}else if(!a.value_text&&!a.value_id)ok=false});saveBtn.disabled=!ok}
function place(m,a){var r=a.getBoundingClientRect();m.style.left=Math.min(window.innerWidth-m.offsetWidth-12,Math.max(12,r.left))+'px';m.style.top=Math.min(window.innerHeight-m.offsetHeight-12,r.bottom+5)+'px'}
function closeFloating(){if(openMenu&&openMenu.parentNode)openMenu.parentNode.removeChild(openMenu);openMenu=null}
function save(){validate();if(saveBtn.disabled)return;saveBtn.disabled=true;var f=fd('save');f.append('automation_id',String(editingId||0));f.append('payload',JSON.stringify({title:titleInput.value.trim(),entity_key:current.entity_key,trigger_id:current.trigger_id,trigger_relation:current.trigger_relation,trigger_offset_value:current.trigger_offset_value,is_active:Number(current.is_active)!==0?1:0,template_key:current.template_key||null,conditions:current.conditions,actions:current.actions}));req(f).then(function(d){toast('success',d.message);closeDrawer();return load()}).catch(function(e){toast('error',e.message)}).then(function(){validate()})}
function toggle(){if(!editingId)return;var f=fd('toggle');f.append('automation_id',String(editingId));f.append('is_active',Number(current.is_active)===1?'0':'1');req(f).then(function(d){toast('success',d.message);current.is_active=Number(current.is_active)===1?0:1;renderBuilder();return load()}).catch(function(e){toast('error',e.message)})}
function del(){if(!editingId||!confirm('Delete this automation?'))return;var f=fd('delete');f.append('automation_id',String(editingId));req(f).then(function(d){toast('success',d.message);closeDrawer();return load()}).catch(function(e){toast('error',e.message)})}
function load(){var f=fd('bootstrap');return req(f).then(function(d){meta=d.meta;automations=d.automations||[];renderCards()}).catch(function(e){document.getElementById('automationContent').innerHTML='<div class="aut-empty">'+esc(e.message)+'</div>';toast('error',e.message)})}
document.getElementById('newAutomation').onclick=function(){current=defaultRule(meta&&meta.entities.length?meta.entities[0].entity_key:'quote');editingId=0;titleInput.value='';openDrawer();renderBuilder()};document.getElementById('closeAutomation').onclick=closeDrawer;overlay.onclick=closeDrawer;saveBtn.onclick=save;titleInput.oninput=validate;document.getElementById('moreAutomation').onclick=function(e){e.stopPropagation();document.getElementById('moreAutomationMenu').classList.toggle('open')};document.getElementById('toggleAutomation').onclick=toggle;document.getElementById('deleteAutomation').onclick=del;document.addEventListener('click',function(e){if(openMenu&&!openMenu.contains(e.target))closeFloating();if(!e.target.closest('.aut-more'))document.getElementById('moreAutomationMenu').classList.remove('open')});document.getElementById('feedbackButton').onclick=function(){toast('success','Thanks. Your automation feedback can be connected to your support workflow.')};document.addEventListener('keydown',function(e){if(e.key==='Escape'&&drawer.classList.contains('open'))closeDrawer()});
load();
})();
</script>
